<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>EMBERLINE — Cinder Yard</title>
<style>
  /* Look plan: dusk yard, ember accent, teal for the Ash defenders. */
  :root {
    --canvas: #171310;
    --surface: #262019;
    --hairline: #3d332a;
    --ink: #f2e9d8;
    --muted: #a89a85;
    --accent: #ff7a1a;
    --teal: #2fae9a;
    --danger: #e5484d;
    --radius-panel: 4px;
    --radius-control: 8px;
    --font-ui: system-ui, -apple-system, 'Segoe UI', sans-serif;
    --font-readout: ui-monospace, 'SF Mono', Menlo, monospace;
  }
  * { box-sizing: border-box; }
  html, body {
    margin: 0;
    height: 100%;
    overflow: hidden;
    background: var(--canvas);
    color: var(--ink);
    font-family: var(--font-ui);
    user-select: none;
  }
  #game, #game canvas { position: fixed; inset: 0; display: block; }
  #hud { position: fixed; inset: 0; pointer-events: none; }

  #crosshair { position: fixed; left: 50%; top: 50%; width: 22px; height: 22px; transform: translate(-50%, -50%); --gap: 4px; }
  #crosshair i { position: absolute; background: var(--ink); opacity: .85; }
  #crosshair i:nth-child(1) { left: 10px; top: calc(0px - var(--gap)); width: 2px; height: 7px; }
  #crosshair i:nth-child(2) { left: 10px; bottom: calc(0px - var(--gap)); width: 2px; height: 7px; }
  #crosshair i:nth-child(3) { top: 10px; left: calc(0px - var(--gap)); height: 2px; width: 7px; }
  #crosshair i:nth-child(4) { top: 10px; right: calc(0px - var(--gap)); height: 2px; width: 7px; }

  #hitmarker { position: fixed; left: 50%; top: 50%; width: 26px; height: 26px; transform: translate(-50%, -50%) rotate(45deg); opacity: 0; transition: opacity 90ms linear; }
  #hitmarker.on { opacity: 1; }
  #hitmarker i { position: absolute; background: var(--accent); }
  #hitmarker i:nth-child(1) { left: 12px; top: 0; width: 2px; height: 8px; }
  #hitmarker i:nth-child(2) { left: 12px; bottom: 0; width: 2px; height: 8px; }
  #hitmarker i:nth-child(3) { top: 12px; left: 0; height: 2px; width: 8px; }
  #hitmarker i:nth-child(4) { top: 12px; right: 0; height: 2px; width: 8px; }

  #damage-overlay { position: fixed; inset: 0; background: radial-gradient(ellipse at center, transparent 55%, rgba(229, 72, 77, 0.55) 100%); opacity: 0; transition: opacity 180ms linear; }
  #damage-overlay.on { opacity: 1; }
  #flash-overlay { position: fixed; inset: 0; background: #fff; opacity: 0; transition: opacity 400ms linear; }

  #topbar { position: fixed; top: 18px; left: 50%; transform: translateX(-50%); display: flex; align-items: center; gap: 16px; font-family: var(--font-readout); }
  #round-label { font-size: 12px; letter-spacing: .12em; color: var(--muted); }
  #score-value { font-size: 22px; }
  #score-value .ember { color: var(--accent); }
  #score-value .ash { color: var(--teal); }
  #timer-value { font-size: 22px; min-width: 76px; text-align: center; }
  #timer-value.freeze { color: var(--accent); }

  #bomb-status { position: fixed; top: 56px; left: 50%; transform: translateX(-50%); font-family: var(--font-readout); font-size: 13px; letter-spacing: .1em; color: var(--accent); }
  #bomb-status.planted { color: var(--danger); }

  #killfeed { position: fixed; top: 18px; right: 24px; display: grid; gap: 4px; font-family: var(--font-readout); font-size: 13px; color: var(--muted); text-align: right; }
  #killfeed .ember { color: var(--accent); }
  #killfeed .ash { color: var(--teal); }

  #health { position: fixed; left: 32px; bottom: 24px; display: flex; align-items: baseline; gap: 10px; }
  #health-num { font-family: var(--font-readout); font-size: 44px; line-height: 1; }
  #health-bar { display: inline-block; width: 120px; height: 6px; background: var(--hairline); border-radius: 3px; overflow: hidden; }
  #health-fill { display: block; height: 100%; width: 100%; background: var(--ink); transition: width 150ms linear; }
  #health-fill.low { background: var(--danger); }
  #armor-num { font-family: var(--font-readout); font-size: 14px; color: var(--teal); }

  #ammo { position: fixed; right: 32px; bottom: 24px; display: flex; align-items: baseline; gap: 8px; font-family: var(--font-readout); font-size: 56px; line-height: 1; letter-spacing: -0.03em; }
  #ammo.empty #ammo-mag { color: var(--accent); }
  #ammo-reserve { font-size: 16px; color: var(--muted); }
  #weapon-name { position: fixed; right: 32px; bottom: 96px; font-family: var(--font-readout); font-size: 13px; color: var(--muted); }
  #grenades { position: fixed; right: 32px; bottom: 116px; font-family: var(--font-readout); font-size: 13px; color: var(--muted); }
  #money { position: fixed; right: 32px; bottom: 140px; font-family: var(--font-readout); font-size: 15px; color: var(--accent); }

  #plant-bar { position: fixed; left: 50%; top: 58%; transform: translateX(-50%); width: 220px; height: 8px; background: var(--hairline); border-radius: 4px; overflow: hidden; }
  #plant-fill { height: 100%; width: 0; background: var(--accent); }

  #banner { position: fixed; left: 50%; top: 34%; transform: translateX(-50%); text-align: center; }
  #banner-title { font-size: 40px; font-weight: 500; letter-spacing: -0.02em; }
  #banner-sub { margin-top: 6px; font-size: 16px; color: var(--muted); }

  #site-markers { position: fixed; inset: 0; }
  .site-marker { position: absolute; transform: translate(-50%, -50%); font-family: var(--font-readout); font-size: 15px; font-weight: 600; padding: 3px 8px; border: 1px solid currentColor; border-radius: 4px; background: rgba(23, 19, 16, 0.6); }
  #marker-a { color: var(--accent); }
  #marker-b { color: var(--teal); }
  #marker-bomb { color: var(--danger); }

  #buy { position: fixed; left: 50%; top: 50%; transform: translate(-50%, -50%); width: min(420px, 92vw); padding: 24px; background: var(--surface); border: 1px solid var(--hairline); border-radius: var(--radius-panel); pointer-events: auto; }
  #buy[hidden] { display: none; }
  #buy h2 { margin: 0 0 4px; font-size: 20px; font-weight: 500; }
  #buy p { margin: 0 0 16px; font-size: 13px; color: var(--muted); }
  #buy-money { font-family: var(--font-readout); color: var(--accent); }
  #buy-list { display: grid; gap: 6px; }
  .buy-row { display: flex; align-items: center; gap: 10px; padding: 9px 12px; background: var(--canvas); border: 1px solid var(--hairline); border-radius: var(--radius-control); color: var(--ink); font: inherit; font-size: 14px; text-align: left; cursor: pointer; }
  .buy-row:hover { border-color: var(--accent); }
  .buy-row.poor { opacity: 0.45; }
  .buy-key { font-family: var(--font-readout); font-size: 12px; color: var(--muted); min-width: 16px; }
  .buy-name { flex: 1; }
  .buy-price { font-family: var(--font-readout); color: var(--accent); }

  .overlay { position: fixed; inset: 0; display: grid; place-items: center; padding: 24px; background: color-mix(in srgb, var(--canvas) 86%, transparent); }
  .overlay[hidden] { display: none; }
  .panel { width: min(460px, 100%); padding: 32px; background: var(--surface); border: 1px solid var(--hairline); border-radius: var(--radius-panel); }
  .panel h1 { margin: 0 0 8px; font-size: 32px; line-height: 1.15; font-weight: 500; letter-spacing: -0.02em; }
  .panel h1 .ember { color: var(--accent); }
  .panel p { margin: 0 0 24px; max-width: 46ch; font-size: 16px; line-height: 1.5; color: var(--muted); }
  #play { font: inherit; font-weight: 500; padding: 12px 16px; border: 1px solid var(--accent); border-radius: var(--radius-control); background: var(--accent); color: var(--canvas); cursor: pointer; }
  #play:hover { background: var(--ink); border-color: var(--ink); }
  #play:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
  .keys { margin: 24px 0 0; padding: 0; list-style: none; display: grid; gap: 8px; font-size: 14px; color: var(--muted); }
  .keys li { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
  .keys kbd { min-width: 24px; padding: 2px 6px; border: 1px solid var(--hairline); border-radius: var(--radius-panel); font-family: var(--font-readout); font-size: 12px; color: var(--ink); text-align: center; }

  @media (prefers-reduced-motion: reduce) {
    #hitmarker, #play, #health-fill { transition-duration: 0.01ms; }
  }
</style>
</head>
<body>
