// The DOM HUD: health, ammo, money, timer, score, bomb status, kill feed, buy menu
// and the overlay panels. It never touches the simulation; main.js pushes numbers
// in and reads the play and buy callbacks out.
const COPY = {
  start: {
    title: 'EMBERLINE',
