      lastMoney = money;
      moneyValue.textContent = `$${money}`;
      buyMoney.textContent = `$${money}`;
    },
    setTimer(seconds, phase) {
      const shown = Math.max(0, Math.ceil(seconds));
      const key = `${shown}:${phase}`;
      if (key === lastTimer) return;
